import 'app_language.dart';

const mistakePracticeKeys = [
  'learn',
  'tryOwn',
  'guidedDone',
  'independentDone',
  'assistedDone',
  'checking',
  'unverified',
  'showPlayed',
  'showBetter',
  'back',
  'reply',
  'noReply',
  'savedLine',
  'lower',
];
final mistakePracticeTranslations = {
  for (final e in _rows.entries) e.key: e.value.split('|'),
};
String mistakePracticeText(
  String key,
  String language, [
  Map<String, String> values = const {},
]) {
  final i = mistakePracticeKeys.indexOf(key);
  if (i < 0) throw ArgumentError.value(key, 'key');
  var text =
      mistakePracticeTranslations[AppLanguageController.resolveCode(
        language,
      )]![i];
  for (final e in values.entries) {
    text = text.replaceAll('{${e.key}}', e.value);
  }
  return text;
}

